public partial class PanelWindow {
 string HeroSecretTipText(int seat){var hero=visualTargets[VisualKey(seat,0)];return ((TextBlock)((ToolTip)hero.ToolTip).Content).Text;}
 void RenderSecretTooltip(int seat,string path){var hero=visualTargets[VisualKey(seat,0)];var tip=(ToolTip)hero.ToolTip;tip.PlacementTarget=hero;tip.IsOpen=true;try{PumpLan(()=>tip.ActualWidth>1&&tip.ActualHeight>1,"Actual WPF tooltip opens");var bitmap=new RenderTargetBitmap((int)Math.Ceiling(tip.ActualWidth),(int)Math.Ceiling(tip.ActualHeight),96,96,PixelFormats.Pbgra32);bitmap.Render(tip);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(bitmap));using(var file=File.Create(path))png.Save(file);CheckNormalWeights(tip);}finally{tip.IsOpen=false;}}
 public void PreviewSecretOwnerScope(string folder){previewRun=true;Directory.CreateDirectory(folder);int before=checks;if(VerificationRun.Visual)VerifySecretOwnerUi(folder);if(VerificationRun.Network)VerifySecretOwnerTcp(folder);File.WriteAllText(Path.Combine(folder,"secret-owner-verification.txt"),"PASS: "+(checks-before)+" assertions; WPF="+VerificationRun.Visual+"; loopback TCP="+VerificationRun.Network+"; own-secret tooltips, hidden opponent names, Scientist owner-only notice, expiry and deduplication. No real mouse or two-computer test.");}
 void VerifySecretOwnerUi(string folder){LeaveLan();localTest=true;ApplyTheme(true,true);ApplyMode(false);SetEffectsLevel(EffectLevel.Off);match=MatchFixture();matchViewSeat=0;awaitHandoff=false;match.ArmSecret(0,new HandCard{Id=990001,CardId="VAN_EX1_287"});match.ArmSecret(1,new HandCard{Id=990002,CardId="VAN_EX1_289"});ShowPage("match");RenderMatch();UpdateLayout();Check(HeroSecretTipText(0).Contains("法术反制")&&HeroSecretTipText(0).Contains(match.Card("VAN_EX1_287").Text),"Owner hover shows secret name and full effect");Check(HeroSecretTipText(1)=="奥秘数量:1","Opponent hover shows only exact public count even on authority");var stack=(StackPanel)((Border)visualTargets[VisualKey(0,0)]).Child;var stats=(TextBlock)stack.Children[1];var mark=stats.Inlines.OfType<Run>().Last();Check(mark.Text=="?"&&ToolTipService.GetToolTip(mark) is ToolTip,"Question-mark inline has its own hover target");Render(Path.Combine(folder,"secret-owner-normal.png"));RenderSecretTooltip(0,Path.Combine(folder,"secret-owner-tooltip.png"));RenderSecretTooltip(1,Path.Combine(folder,"secret-opponent-tooltip.png"));
  ApplyMode(true);RenderMatch();UpdateLayout();Check(HeroSecretTipText(0).Contains("法术反制")&&HeroSecretTipText(1)=="奥秘数量:1"&&Width==392&&Height==300,"Minimal mode keeps private hover details within fixed size");var label=(TextBlock)((Border)visualTargets[VisualKey(0,0)]).Child;Check(label.Inlines.OfType<Run>().Last().Text=="?","Minimal question mark remains a hover target");ApplyMode(false);match.DestroySecrets(0);match.Players[0].Deck.Clear();match.Players[0].Deck.Add("VAN_EX1_287");var scientist=match.Summon(0,"FP1_004");var attacker=match.Summon(0,"VAN_CS2_182");attacker.SummonTurn=0;scientist.DamageTaken=scientist.MaxHealth;match.Cleanup();status.Text="原状态";pending="attack";pendingId=attacker.Id;RenderMatch();Check(status.Text.Contains("疯狂的科学家置入奥秘：法术反制")&&pending=="attack"&&pendingId==attacker.Id,"Scientist notice works with effects off and preserves pending attack");var timer=secretNoticeTimer;RenderMatch();Check(Object.ReferenceEquals(timer,secretNoticeTimer),"Repeated redraw does not restart private hint");PumpLan(()=>secretNoticeTimer==null,"Private hint expires after two seconds");Check(status.Text=="原状态","Expired hint restores previous status");RenderMatch();Check(secretNoticeTimer==null,"Consumed hint does not replay");ClearPending();ApplyMode(true);match.DestroySecrets(0);match.Players[0].Deck.Add("VAN_EX1_287");match.PutSecretFromDeck(0);RenderMatch();Check(status.Text.Contains("法术反制")&&matchEffectsCanvas.Visibility==Visibility.Collapsed,"Minimal mode shows basic private status notice without animation");Render(Path.Combine(folder,"secret-owner-minimal-notice.png"));awaitHandoff=true;RenderMatch();Check(secretNoticeTimer==null&&!status.Text.Contains("法术反制"),"Local handoff removes previous player's private hint");awaitHandoff=false;ApplyMode(false);localTest=false;ClearOwnSecretNotice();}
 void VerifySecretOwnerTcp(string folder){LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetEffectsLevel(EffectLevel.Off);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();guest.ApplyTheme(true,true);guest.ApplyMode(false);guest.SetEffectsLevel(EffectLevel.Off);try{
  lanPort.Text=FreeLanPort().ToString();lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");lanDeck.SelectedIndex=0;BeginLan(true);guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="MAGE");guest.lanDeck.SelectedIndex=0;guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Secret-owner peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan synchronized");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Secret-owner opening complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=p.MaxMana=10;}g.ArmSecret(0,new HandCard{Id=991001,CardId="VAN_EX1_287"});g.ArmSecret(1,new HandCard{Id=991002,CardId="VAN_EX1_289"});PublishLan();RenderMatch();PumpLan(()=>guest.match.SecretCards(1).Contains("VAN_EX1_289"),"Guest receives own equipped secret identity");Check(HeroSecretTipText(0).Contains("法术反制")&&HeroSecretTipText(1)=="奥秘数量:1","Host hover hides guest's secret despite authority access");Check(guest.HeroSecretTipText(1).Contains("寒冰护体")&&guest.HeroSecretTipText(0)=="奥秘数量:1","Guest hover shows own detail and opponent count only");Check(guest.match.SecretCards(0).Length==0,"Guest model has no opponent secret identities");
  g.DestroySecrets(0);g.Players[0].Deck.Clear();g.Players[0].Deck.Add("VAN_EX1_287");var scientist=g.Summon(0,"FP1_004");int fire=NaxxUiHand(g,"VAN_CS2_029",1);PublishLan();DoMatch("end");PumpLan(()=>guest.match.Active==1&&guest.match.Players[1].Hand.Any(h=>h.Id==fire),"Guest can target host Scientist");guest.BeginCard(fire);guest.ClickMatchTarget(new MatchTarget(0,scientist.Id));PumpLan(()=>!guest.lanWaiting&&g.Players[0].SecretCount==1,"Host Scientist resolves");Check(status.Text.Contains("法术反制")&&guest.secretNoticeText==null,"Host-only Scientist notice never appears on guest");Check(guest.HeroSecretTipText(0)=="奥秘数量:1"&&HeroSecretTipText(0).Contains("法术反制"),"Scientist updates host hover and guest anonymous count");Check(!JsonData.Serializer().Serialize(LanProtocol.View(g,1,"private",1)).Contains("VAN_EX1_287"),"Host fetched secret identity stays off guest wire");
  ClearOwnSecretNotice();guest.ClearOwnSecretNotice();guest.DoMatch("end");PumpLan(()=>!guest.lanWaiting&&g.Active==0,"Host turn for guest Scientist");g.DestroySecrets(1);g.Players[1].Deck.Clear();g.Players[1].Deck.Add("VAN_EX1_289");scientist=g.Summon(1,"FP1_004");g.Players[0].Mana=10;fire=NaxxUiHand(g,"VAN_CS2_029");PublishLan();PumpLan(()=>guest.match.Players[1].Board.Any(u=>u.Id==scientist.Id),"Guest Scientist fixture synchronized");BeginCard(fire);ClickMatchTarget(new MatchTarget(1,scientist.Id));PumpLan(()=>guest.match.Players[1].SecretCount==1&&guest.status.Text.Contains("寒冰护体"),"Guest receives Scientist owner-only notice");Check(secretNoticeText==null&&HeroSecretTipText(1)=="奥秘数量:1","Host gets no guest Scientist hint or tooltip identity");Check(guest.HeroSecretTipText(1).Contains("寒冰护体")&&guest.match.SecretCards(0).Length==0,"Guest owns fetched identity but never opponent secrets");var timer=guest.secretNoticeTimer;PublishLan();var start=DateTime.UtcNow;PumpLan(()=>DateTime.UtcNow-start>TimeSpan.FromMilliseconds(60),"Repeated snapshot delivered");Check(Object.ReferenceEquals(timer,guest.secretNoticeTimer),"Repeated TCP snapshot does not restart owner notice");Check(!g.Log.Any(l=>l.Contains("法术反制")||l.Contains("寒冰护体")),"Shared record does not leak either untriggered secret");Render(Path.Combine(folder,"secret-owner-host-tcp.png"));guest.Opacity=1;guest.Render(Path.Combine(folder,"secret-owner-guest-tcp.png"));guest.Opacity=0;
 }finally{guest.ClearOwnSecretNotice();guest.LeaveLan();guest.Close();LeaveLan();}}
